// Legal pages (privacy/, terms/, terms/business/), generated by tools/sync_legal.py.
// Shows the English or Arabic text and applies the site's saved theme.
// Language: ?lang=ar|en in the address (used by the mobile apps), otherwise the
// language chosen on the main site (Arabic stays Arabic, every other language reads English).
(function () {
    function readStored(key) {
        try { return localStorage.getItem(key); } catch { return null; }
    }

    var root = document.documentElement;

    // Theme
    var theme = readStored('theme') === 'dark' ? 'dark' : 'light';
    root.setAttribute('data-theme', theme);
    var logo = document.querySelector('.legal-logo');
    if (logo) logo.src = '/assets/logo-mark-' + theme + '.svg';

    // Language
    var asked = new URLSearchParams(window.location.search).get('lang');
    var lang = asked === 'ar' || asked === 'en' ? asked : (readStored('app_lang') === 'ar' ? 'ar' : 'en');
    root.setAttribute('lang', lang);
    root.setAttribute('dir', lang === 'ar' ? 'rtl' : 'ltr');

    document.querySelectorAll('[data-lang-part]').forEach(function (el) {
        el.hidden = el.getAttribute('data-lang-part') !== lang;
    });
    document.querySelectorAll('.legal-lang .chip').forEach(function (chip) {
        var on = chip.getAttribute('data-lang') === lang;
        chip.classList.toggle('active', on);
        if (on) chip.setAttribute('aria-current', 'page');
        else chip.removeAttribute('aria-current');
    });

    var title = document.querySelector('[data-lang-part="' + lang + '"] h1');
    if (title) document.title = title.textContent;

    var year = document.querySelector('.copyright-year');
    if (year) year.textContent = String(new Date().getFullYear());
})();
